// --- Normalize raw source payload -> exact DB columns for `listings` ---
const cfg = $('Set: Run Config').first().json;
const targetCur = cfg.currency_target || 'ILS';
// fallback FX to ILS. In prod replace with an exchange-rate HTTP node.
const fx = { ILS: 1, USD: 3.7, EUR: 4.0, GBP: 4.7 };
const crypto = require('crypto');

const resp = $input.first().json || {};
function pick(obj, path) { return (path || '').split('.').filter(Boolean).reduce((o, k) => (o == null ? o : o[k]), obj); }
let rows = pick(resp, cfg.list_path) || resp.results || resp.data || resp.AllResults || resp.elementList || (Array.isArray(resp) ? resp : []);
if (!Array.isArray(rows)) rows = [];

const num = v => { if (v == null || v === '') return null; const n = parseFloat(String(v).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? null : n; };
const str = v => (v == null ? null : String(v).trim() || null);

function mapGeneric(r) {
  return {
    source_id: String(r.id ?? r.listingId ?? r.propertyCode ?? r.ID ?? r.url ?? JSON.stringify(r).slice(0, 60)),
    url: str(r.url ?? r.link),
    deal_type: str(r.dealType) || cfg.deal_type || 'sale',
    property_kind: str(r.propertyType ?? r.type) || 'apartment',
    city: str(r.city ?? r.town ?? (r.address && r.address.city)) || cfg.city || null,
    neighborhood: str(r.neighborhood ?? r.district),
    street: str(r.street), house_no: str(r.houseNumber),
    lat: num(r.latitude ?? r.lat ?? (r.geo && r.geo.lat)), lon: num(r.longitude ?? r.lon ?? (r.geo && r.geo.lon)),
    gush: str(r.gush), helka: str(r.helka),
    price_amount: num(r.price ?? r.priceAmount ?? r.Price),
    price_currency: str(r.currency) || cfg.source_currency || 'ILS',
    built_sqm: num(r.size ?? r.builtArea ?? r.area ?? r.squareMeters),
    plot_sqm: num(r.plotArea ?? r.lotSize ?? r.landArea),
    balcony_sqm: num(r.balconyArea),
    rooms: num(r.rooms ?? r.roomsNumber ?? r.bedrooms),
    floor: num(r.floor), total_floors: num(r.totalFloors ?? r.floors),
    furnished: r.furnished === true ? 'yes' : r.furnished === false ? 'no' : (str(r.furnished) || 'unknown'),
    parking: num(r.parking ?? r.parkingSpaces),
    elevator: typeof r.hasLift === 'boolean' ? r.hasLift : (typeof r.elevator === 'boolean' ? r.elevator : null),
    condition: str(r.status ?? r.condition) || 'unknown',
    year_built: num(r.yearBuilt ?? r.constructionYear),
    raw_text: str(r.description ?? r.summary ?? r.text) || ''
  };
}

// nadlan (רשות המסים) — keys differ; inspect a live response and adjust.
function mapNadlan(r) {
  return {
    source_id: String(r.KEYVALUE ?? r.DEALNMBR ?? `${r.GUSH || ''}-${r.PARCEL || ''}-${r.DEALDATE || ''}`),
    url: null, deal_type: 'sale',
    property_kind: str(r.PROPERTYTYPE) || 'apartment',
    city: str(r.SETL_NAME) || cfg.city || null,
    neighborhood: str(r.NEIGHBORHOOD), street: str(r.STREET_NAME), house_no: str(r.HOUSE_NUMBER),
    lat: num(r.LAT), lon: num(r.LON), gush: str(r.GUSH), helka: str(r.PARCEL),
    price_amount: num(r.DEALAMOUNT ?? r.PRICE), price_currency: 'ILS',
    built_sqm: num(r.DEALNATURE ?? r.BUILDINGAREA), plot_sqm: null, balcony_sqm: null,
    rooms: num(r.ASSETROOMNUM ?? r.ROOMS), floor: num(r.FLOORNO), total_floors: null,
    furnished: 'unknown', parking: null, elevator: null,
    condition: 'unknown', year_built: num(r.BUILDINGYEAR ?? r.YEARBUILT),
    raw_text: `עסקת השוואה ${r.DEALDATE || ''}`
  };
}

const mapper = ({ nadlan: mapNadlan, idealista: mapGeneric, generic: mapGeneric })[cfg.map || 'generic'];

return rows.map(r => {
  const m = mapper(r);
  const rate = (fx[m.price_currency] || 1) / (fx[targetCur] || 1);
  const price_ils = m.price_amount != null ? Math.round(m.price_amount * rate) : null;
  const content_hash = crypto.createHash('sha1')
    .update(JSON.stringify([m.price_amount, m.built_sqm, m.rooms, m.furnished, m.condition, m.url])).digest('hex');
  return {
    json: {
      source: cfg.source, source_id: m.source_id, url: m.url, country: cfg.country || 'IL',
      deal_type: m.deal_type, property_kind: m.property_kind,
      city: m.city, neighborhood: m.neighborhood, street: m.street, house_no: m.house_no,
      lat: m.lat, lon: m.lon, gush: m.gush, helka: m.helka,
      price_amount: m.price_amount, price_currency: m.price_currency, price_ils,
      built_sqm: m.built_sqm, plot_sqm: m.plot_sqm, balcony_sqm: m.balcony_sqm,
      rooms: m.rooms, floor: m.floor, total_floors: m.total_floors,
      furnished: m.furnished, parking: m.parking, elevator: m.elevator,
      condition: m.condition, year_built: m.year_built,
      content_hash, raw: r, raw_text: m.raw_text, scraped_at: new Date().toISOString()
    }
  };
});

// Assemble the analyst-agent input for each listing item.
const cfg = $('Set: Run Config').first().json;
const n = $('Code: Normalize').item.json;

const listing = { ...n };
delete listing.raw;            // keep the prompt lean

let comparables = [];
try {
  const cmp = $json;
  const rows = cmp.AllResults || cmp.results || cmp.data || [];
  comparables = (Array.isArray(rows) ? rows : []).slice(0, 20);
} catch (e) { comparables = []; }

const area = {
  price_trend_12m_pct: cfg.area_price_trend_12m_pct ?? null,
  rent_yield_pct: cfg.area_rent_yield_pct ?? null,
  quality_score: cfg.area_quality_score ?? null
};

return [{ json: { listing, comparables, area, buyer_profile: cfg.buyer_profile || {} } }];

