// Composite 0..100 score + split flat rows for the two DB tables.
const src = $('Code: Build Agent Input').item.json;
const listing = src.listing;
const comps = src.comparables || [];
const area = src.area || {};
const e = $json.output || $json;

// weights (override via Set: Run Config -> weights if desired)
const W = (($('Set: Run Config').first().json.weights) || {
  price_vs_market: 0.30, size_fit: 0.15, plot_bonus: 0.10,
  area_quality: 0.20, future_upside: 0.15, condition_furnish: 0.10
});

const clamp = (x, a, b) => Math.max(a, Math.min(b, x));

// price vs market: negative gap (below market) is good
const gap = Number(e?.valuation?.market_gap_pct ?? 0);
const price_vs_market = clamp(50 - gap * 300, 0, 100); // -10% gap -> 80 ; +10% -> 20

// size fit vs requested built_sqm (buyer profile) or neutral 60
const want = Number(src.buyer_profile?.built_sqm_target ?? 0);
const built = Number(listing.built_sqm ?? 0);
const size_fit = want && built ? clamp(100 - Math.abs(built - want) / want * 120, 0, 100) : 60;

const plot_bonus = listing.plot_sqm ? clamp(40 + Math.log10(listing.plot_sqm) * 20, 0, 100) : 40;
const area_quality = clamp(Number(area.quality_score ?? 55), 0, 100);
const future_upside = 50; // filled by WF03 later
const condMap = { new: 90, renovated: 80, good: 65, needs_renovation: 40, unknown: 55 };
const furnMap = { yes: 8, partial: 4, no: 0, unknown: 0 };
const condition_furnish = clamp((condMap[listing.condition] ?? 55) + (furnMap[listing.furnished] ?? 0), 0, 100);

const parts = { price_vs_market, size_fit, plot_bonus, area_quality, future_upside, condition_furnish };
let score = 0, wsum = 0;
for (const k of Object.keys(W)) { score += (parts[k] ?? 0) * W[k]; wsum += W[k]; }
score = Math.round(score / (wsum || 1));

const db_listing = { ...listing };
delete db_listing.raw_text; delete db_listing.scraped_at;

const v = e.valuation || {};
const uc = e.use_classification || {};
const fe = e.furnishing_effect || {};
const db_enriched = {
  estimated_market_value_ils: v.estimated_market_value_ils ?? null,
  value_low_ils: v.value_low_ils ?? null,
  value_high_ils: v.value_high_ils ?? null,
  price_per_sqm_ils: v.price_per_sqm_ils ?? null,
  price_per_plot_sqm_ils: v.price_per_plot_sqm_ils ?? null,
  market_gap_pct: v.market_gap_pct ?? null,
  valuation_confidence: v.confidence ?? null,
  furnished_state: fe.furnished_state ?? null,
  furnish_value_adj_ils: fe.value_adjustment_ils ?? null,
  residential_score: uc.residential_score ?? null,
  investment_score: uc.investment_score ?? null,
  gross_rent_yield_pct: uc.estimated_gross_rent_yield_pct ?? null,
  recommended_use: uc.recommended_use ?? null,
  red_flags: JSON.stringify(e.red_flags ?? []),
  buyer_fit_score: e.buyer_fit?.fit_score ?? null,
  rationale_he: e.rationale_he ?? null,
  score,
  score_breakdown: JSON.stringify(parts),
  model: 'claude-sonnet-5'
};

return [{ json: { db_listing, db_enriched, raw: listing } }];

const err = $json;
return [{ json: {
  source: err?.workflow?.name || 'WF01',
  stage: err?.execution?.lastNodeExecuted || 'unknown',
  message: (err?.execution?.error?.message || err?.error?.message || 'unknown error').slice(0, 2000),
  payload: JSON.stringify(err).slice(0, 8000)
}}];
